import json,re
from html import unescape
from collections import Counter
from html.parser import HTMLParser
s=json.load(open('source.json')); a=json.load(open('answer.json')); r=json.load(open('reference-targets.json'))
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
class Validator(HTMLParser):
 def handle_starttag(self,tag,attrs):
  assert tag in allowed,tag
  for k,v in attrs: assert k in ['rowspan','colspan'] and v.isdigit(),(k,v)
 def handle_startendtag(self,tag,attrs): self.handle_starttag(tag,attrs)
def plain(v): return unescape(re.sub(r'<["'^>]+>'"','',v or ''))
assert len(a)==len(s)==24
for src,out in zip(s,a):
 for f in ['code_id','source_id','source_sha256','number']: assert out[f]==src[f],f
 for f in ['proposed_xml','reason','review_notes','status','substantive_impact','reference_checks']: assert f in out,f
 im=out['substantive_impact']; assert im['version']==1
 for f in ['assessment','scope_limitations','new_burdens_review']: assert len(im[f])>=40,(src['number'],f)
 if src['benefit_check_required']: assert len(out['benefit_review'])>=100
 expected=r['requirements'][src['code_id']+'|'+src['source_id']]
 assert [x['target_key'] for x in out['reference_checks']]==expected
 for x in out['reference_checks']:
  assert x['view_sha256']==r['targets'][x['target_key']]['view_sha256']
  assert len(x['assessment'])>=80
 if out['status']=='retained_unchanged':
  assert out['proposed_xml'] is None and out['classification']=='retained_necessary'
  assert im['classification']=='retained_necessary' and im['effects']==[]
 else:
  assert isinstance(out['proposed_xml'],str) and len(out['proposed_xml'])>10
  Validator().feed(out['proposed_xml'])
  if out.get('change_type')=='full_repeal':
   assert plain(out['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé'))
   assert out['repeal_policy_id']=='editorial_direction_2026_10_19' and len(out['repeal_scope'])>=30
  elif out.get('change_type')=='normative_reduction':
   assert out['reform_policy_id']=='editorial_direction_2026_10_19'
   assert all(len(p)>=30 for p in out['removed_provisions'])
 for e in im['effects']:
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id'])
  assert 6<=len(e['measure_id'])<=96
  for q,body in [('source_quote',src['source_xml']),('proposed_quote',out['proposed_xml'])]:
   assert len(e[q])>=12 and e[q] in plain(body),(src['number'],q,e[q])
 print(src['number'],out['status'],im['classification'],'renvois',len(expected),'effets',len(im['effects']))
print('TOTAL',len(a),'STATUTS',dict(Counter(x['status'] for x in a)),'EFFETS',sum(len(x['substantive_impact']['effects']) for x in a))
print('Toutes les validations structurelles ont réussi ; elles ne constituent pas une validation juridique.')
PY"

